    lasso_scores.append(cross_val_score(lasso, X, y, cv=5, scoring='r2').mean())
    lasso.fit(X, y)
    lasso_coef_norms.append(np.linalg.norm(lasso.coef_))
    lasso_selected_features.append(np.sum(lasso.coef_ != 0))

